.serif{font-family: "Instrument Serif", serif; letter-spacing: -0.05em;}
.mist-button{position: relative; overflow: hidden; border-radius: 999px; background: rgba(255, 255, 255, 0.18); backdrop-filter: blur(30px) saturate(1.1); border-width: medium; border-style: none; border-color: currentcolor; border-image: none; color: white; transition: 0.7s cubic-bezier(0.16, 1, 0.3, 1); box-shadow: rgba(255, 255, 255, 0.28) 0px 1px 0px inset, rgba(10, 50, 25, 0.16) 0px 12px 50px;}
.mist-button::before{content: ""; position: absolute; inset: 0px; background: radial-gradient(circle, rgba(255, 255, 255, 0.22), transparent 70%); opacity: 0; transition: 0.7s;}
.mist-button:hover{transform: translateY(-4px) scale(1.02); background: rgba(255, 255, 255, 0.24);}
.mist-button:hover::before{opacity: 1; transform: scale(1.3);}
.hero-video{position: absolute; inset: 0px; width: 100%; height: 100%; object-fit: cover; animation: 18s ease-in-out 0s infinite alternate none running zoom;}
.hero-overlay{position: absolute; inset: 0px; background: radial-gradient(circle at center top, rgba(255, 255, 255, 0.16), transparent 30%), linear-gradient(rgba(0, 0, 0, 0.1), rgba(0, 0, 0, 0.45));}
.condense{opacity: 0; filter: blur(22px); transform: translateY(40px) scale(0.96); animation: 1.4s cubic-bezier(0.16, 1, 0.3, 1) 0s 1 normal forwards running condense;}
.condense:nth-child(2){animation-delay: 0.18s;}
.condense:nth-child(3){animation-delay: 0.32s;}
